        $attempts = json_decode($json, true);

        if (!is_array($attempts)) {
            throw new RuntimeException('Data assessment attempt tidak valid.');
        }

        $attemptsCreated = 0;
        $attemptsSkipped = 0;
        $answersCreated = 0;

        DB::transaction(function () use ($attempts, &$attemptsCreated, &$attemptsSkipped, &$answersCreated): void {
            foreach ($attempts as $attempt) {
                $exists = DB::table('assessment_attempts')
                    ->where('user_id', $attempt['user_id'])
                    ->where('assessment_id', $attempt['assessment_id'])
                    ->where('completed_at', $attempt['completed_at'])
                    ->exists();

                if ($exists) {
                    $attemptsSkipped++;

                    continue;
                }

                $attemptId = DB::table('assessment_attempts')->insertGetId([
                    'user_id' => $attempt['user_id'],
                    'assessment_id' => $attempt['assessment_id'],
                    'attempt_number' => $attempt['attempt_number'],
                    'status' => $attempt['status'],
                    'finished_reason' => $attempt['finished_reason'],
                    'started_at' => $attempt['started_at'],
                    'submitted_at' => $attempt['submitted_at'],
                    'completed_at' => $attempt['completed_at'],
                    'total_score' => $attempt['total_score'],
                    'created_at' => $attempt['completed_at'],
                    'updated_at' => $attempt['completed_at'],
                ]);

                $attemptsCreated++;

                foreach ($attempt['answers'] as $answer) {
                    DB::table('assessment_answers')->insert([
                        'assessment_attempt_id' => $attemptId,
                        'question_id' => $answer['question_id'],
                        'question_option_id' => $answer['question_option_id'],
                        'answer_text' => $answer['answer_text'],
                        'is_final' => $answer['is_final'],
                        'answered_at' => $attempt['completed_at'],
                        'created_at' => $attempt['completed_at'],
                        'updated_at' => $attempt['completed_at'],
                    ]);

                    $answersCreated++;
                }
            }
        });

        $this->command?->info(
            "Assessment attempt selesai: {$attemptsCreated} dibuat, {$attemptsSkipped} dilewati (sudah ada). Total jawaban: {$answersCreated}."
        );
    }
}
